export const ACTIONS={forward:'Acelerar / inclinar adelante',back:'Retroceder / inclinar atrás',left:'Girar izquierda',right:'Girar derecha',jump:'Saltar / doble salto / flip',boost:'Turbo',drift:'Derrape / air roll',rollLeft:'Air roll izquierdo',rollRight:'Air roll derecho',camera:'Cámara de balón',reset:'Reiniciar saque',skip:'Saltar repetición'};
export const PRESETS={original:{forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD',jump:'Mouse2',boost:'Mouse0',drift:'ShiftLeft',rollLeft:'KeyQ',rollRight:'KeyE',camera:'Space',reset:'KeyR',skip:'Enter'},keyboard:{forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD',jump:'Space',boost:'ShiftLeft',drift:'KeyX',rollLeft:'KeyQ',rollRight:'KeyE',camera:'KeyC',reset:'KeyR',skip:'Enter'}};
export const keyName=code=>({Space:'Espacio',ShiftLeft:'Shift izq.',ShiftRight:'Shift der.',ControlLeft:'Ctrl izq.',ControlRight:'Ctrl der.',Mouse0:'Mouse izquierdo',Mouse1:'Mouse central',Mouse2:'Mouse derecho',Enter:'Enter',ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→','':'Sin asignar'}[code]||code.replace(/^Key|^Digit/,''));
export function createControls(front,onChange){
 let preset='original',bindings={...PRESETS.original},waiting=null;
 function load(saved){if(!saved)return;preset=['original','keyboard','custom'].includes(saved.preset)?saved.preset:'original';bindings={...PRESETS[preset==='keyboard'?'keyboard':'original']};for(const action of Object.keys(ACTIONS))if(typeof saved.bindings?.[action]==='string'&&/^[A-Za-z0-9]*$/.test(saved.bindings[action])&&!['Escape','Tab'].includes(saved.bindings[action]))bindings[action]=saved.bindings[action];try{localStorage.setItem('rocket-controls',JSON.stringify({preset,bindings}))}catch{}}
 try{load(JSON.parse(localStorage.getItem('rocket-controls')||'null'))}catch{}
 function save(){try{localStorage.setItem('rocket-controls',JSON.stringify({preset,bindings}))}catch{}onChange()}
 function html(){return `<div class="page-title">CONFIGURACIÓN</div><section class="panel controls-panel"><h2>CONTROLES</h2><div class="control-presets"><button data-controls-preset="original" class="${preset==='original'?'selected':''}">ORIGINALES · MOUSE</button><button data-controls-preset="keyboard" class="${preset==='keyboard'?'selected':''}">PC · SIN MOUSE</button></div><p class="muted">${preset==='custom'?'Controles personalizados. ':''}Pulsa una asignación y luego la tecla o botón que quieras usar. Esc cancela. Supr borra. Esc abre el menú y Tab muestra los puntos; están reservados. Se guarda automáticamente.</p><div class="binding-list">${Object.entries(ACTIONS).map(([action,label])=>`<div><span>${label}</span><button data-binding="${action}" class="${waiting===action?'selected':''}">${waiting===action?'PULSA UNA TECLA…':keyName(bindings[action])}</button></div>`).join('')}</div><p class="muted">En el aire, W/S inclinan el carro y A/D lo orientan. Mantén derrape con A/D para air roll. El mando sigue funcionando.</p></section><button data-action="home" class="back">‹ VOLVER</button>`}
 front.addEventListener('click',e=>{const p=e.target.closest('[data-controls-preset]'),b=e.target.closest('[data-binding]');if(p){waiting=null;preset=p.dataset.controlsPreset;bindings={...PRESETS[preset]};save()}else if(b){waiting=b.dataset.binding;onChange()}});
 function capture(e,code){if(!waiting||document.body.dataset.screen!=='settings')return;e.preventDefault();e.stopImmediatePropagation();if(code==='Escape'||code==='Tab'){waiting=null;onChange();return}if(code==='Delete'||code==='Backspace')code='';const old=bindings[waiting];if(code)for(const action of Object.keys(ACTIONS))if(action!==waiting&&bindings[action]===code)bindings[action]=old;bindings[waiting]=code;preset='custom';waiting=null;save()}
 addEventListener('keydown',e=>capture(e,e.code),true);addEventListener('mousedown',e=>capture(e,'Mouse'+e.button),true);
 return{html,load,snapshot:()=>({preset,bindings:{...bindings}}),down:(keys,action)=>!!(bindings[action]&&keys[bindings[action]]),matches:(action,code)=>bindings[action]===code,used:code=>Object.values(bindings).includes(code),hint:()=>`${keyName(bindings.forward)}/${keyName(bindings.back)} Conducir · ${keyName(bindings.jump)} Saltar · ${keyName(bindings.boost)} Turbo · ${keyName(bindings.drift)} Derrape · ${keyName(bindings.camera)} Cámara · TAB Puntos · ESC Menú`};
}


